head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil52101";
scwin.form = null;
scwin.upd_attachFiles2 = null;
scwin.upd_attachFiles2_2 = null;
scwin.upd_attachFiles2_3 = null;
scwin.upd_attachFiles2_4 = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — searchType, attachList2, uploadCode, prtDepoNo

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.upd_attachFiles2 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles2"]');
        scwin.upd_attachFiles2_2 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles2_2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles2_2"]');
        scwin.upd_attachFiles2_3 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles2_3') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles2_3"]');
        scwin.upd_attachFiles2_4 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles2_4') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles2_4"]');
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil52101.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "ipt_prtDepoReopnYn", fn: function(){ return ((dma_loadDetailList.get("prtdepoReopnYn") ?? (() => { throw new Error("unresolved:" + "loadDetailList.prtdepoReopnYn"); })()) === 'Y'); } }, { id: "txt_text61", fn: function(){ return ((dma_loadDetailList.get("prtdepoReopnYn") ?? (() => { throw new Error("unresolved:" + "loadDetailList.prtdepoReopnYn"); })()) === 'Y'); } }, { id: "if_searchType", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '4'); } }, { id: "if_listProcsStatCd", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '5' && (dma_loadDetailList.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "loadDetailList.listProcsStatCd"); })()) === '38'); } }, { id: "if_searchType_2", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '4'); } }, { id: "txt_text97", fn: function(){ return ((((dma_pageContext.get("attachList2") ?? "")) && typeof ((dma_pageContext.get("attachList2") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("attachList2") ?? "")).getRowCount() : ((((dma_pageContext.get("attachList2") ?? "")) == null) ? 0 : (((dma_pageContext.get("attachList2") ?? "")).length || 0))) === 2); } }, { id: "txt_text100", fn: function(){ return ((((dma_pageContext.get("attachList2") ?? "")) && typeof ((dma_pageContext.get("attachList2") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("attachList2") ?? "")).getRowCount() : ((((dma_pageContext.get("attachList2") ?? "")) == null) ? 0 : (((dma_pageContext.get("attachList2") ?? "")).length || 0))) !== 2); } }, { id: "if_listProcsStatCd_2", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '5' && (dma_loadDetailList.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "loadDetailList.listProcsStatCd"); })()) === '38'); } }, { id: "if_prtdepoReopnYn", fn: function(){ return ((dma_loadDetailList.get("prtdepoReopnYn") ?? (() => { throw new Error("unresolved:" + "loadDetailList.prtdepoReopnYn"); })()) === 'Y'); } }, { id: "tr_76", fn: function(){ return ((dma_loadDetailList.get("prtdepoReopnYn") ?? (() => { throw new Error("unresolved:" + "loadDetailList.prtdepoReopnYn"); })()) === 'Y'); } }, { id: "tr_87", fn: function(){ return ((dma_loadDetailList.get("prtdepoReopnYn") ?? (() => { throw new Error("unresolved:" + "loadDetailList.prtdepoReopnYn"); })()) === 'Y'); } }, { id: "btn_filePrtDepoWithd", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '4'); } }, { id: "btn_filePrtDepoWithd_2", fn: function(){ return ((dma_pageContext.get("searchType") ?? "") === '5' && ((dma_loadDetailList.get("lstApprovYn") ?? (() => { throw new Error("unresolved:" + "loadDetailList.lstApprovYn"); })()) === '7' && (dma_loadDetailList.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "loadDetailList.listProcsStatCd"); })()) === '38')); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["usrId"] ?? "") + "/" + String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["corpUsrNm"] ?? ""); } },
        { childId: "__rb1", fn: function () { return String(dma_loadDetailList.get("comNm")) + "(" + String(dma_loadDetailList.get("isurCd")) + ")"; } },
        { childId: "__rb3", fn: function () { return String(dma_loadDetailList.get("fstPrtdepoShrs")) + " 주"; } },
        { childId: "__rb4", fn: function () { return String(dma_loadDetailList.get("prtdepoWithdShrs")) + " 주"; } },
        { childId: "__rb7", fn: function () { return String(dma_loadDetailList.get("lstPrtdepoShrs")) + " 주"; } },
        { childId: "__rb8", fn: function () { return String(dlt_attachList.getCellData(0, "attachFileNm")); } },
        { childId: "__rb9", fn: function () { return String(dlt_attachList.getCellData(1, "attachFileNm")); } },
        { childId: "btn_FileDown", fn: function () { return String(dlt_attachList1.getCellData(0, "attachFileNm")); } },
        { childId: "__rb10", fn: function () { return " 기 첨부된 파일 : " + String(dlt_attachList2.getCellData(0, "attachFileNm")); } },
        { childId: "__rb11", fn: function () { return " " + String(dlt_attachList2.getCellData(0, "attachFileNm")); } },
        { childId: "__rb12", fn: function () { return " 기 첨부된 파일 : " + String(dlt_attachList2.getCellData(1, "attachFileNm")); } },
        { childId: "__rb13", fn: function () { return " " + String(dlt_attachList2.getCellData(1, "attachFileNm")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    const uploadCode = (String(((dma_pageContext.get("uploadCode") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCode") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("uploadCode") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCode") ?? ""))));
    const prtDepoNo = (String(((dma_pageContext.get("prtDepoNo") ?? "")) == null ? '' : ((dma_pageContext.get("prtDepoNo") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("prtDepoNo") ?? "")) == null ? '' : ((dma_pageContext.get("prtDepoNo") ?? ""))));
    const searchType = (String(((dma_pageContext.get("searchType") ?? "")) == null ? '' : ((dma_pageContext.get("searchType") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("searchType") ?? "")) == null ? '' : ((dma_pageContext.get("searchType") ?? ""))));
    if (searchType !== '' && searchType !== '0') {
        if (uploadCode === '0') {
            await $c.win.alert('저장되었습니다.');
        } else {
            if (uploadCode === '1') {
                await $c.win.alert('해당유형의 파일은 업로드할 수 없습니다.');
            } else {
                if (uploadCode === '2') {
                    await $c.win.alert('업로드 하려는 파일의 크기가 허용한도를 초과 하였습니다.');
                } else {
                    if (prtDepoNo === '') {
                        await $c.win.alert('저장시 오류가 발생하였습니다.');
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.form = (document.prtDepoForm || { elements: [] });
        searchType = 'null';
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil52101.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 2건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId","corpUsrNm"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil52101' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_FileDown_onclick
 * @description btn_FileDown 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_FileDown_onclick = async function(e){
    try {
        await scwin.fileDown('' + dlt_attachList1.getCellData(0, "prtdepoId") + '','' + dlt_attachList1.getCellData(0, "prtdepoWithdApplSeq") + '','' + dlt_attachList1.getCellData(0, "attachFileSeq") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil52101.btn_FileDown_onclick' }); }
};

/**
 * @method
 * @name btn_filePrtDepoWithd_onclick
 * @description 「제출」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_filePrtDepoWithd_onclick = async function(e){
    try {
        await scwin.filePrtDepoWithd(4)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil52101.btn_filePrtDepoWithd_onclick' }); }
};

/**
 * @method
 * @name btn_filePrtDepoWithd_2_onclick
 * @description 「제출」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_filePrtDepoWithd_2_onclick = async function(e){
    try {
        await scwin.filePrtDepoWithd(5)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil52101.btn_filePrtDepoWithd_2_onclick' }); }
};

/**
 * @method
 * @name btn_list_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_list_onclick = function(e){
    try {
        scwin.list()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil52101.btn_list_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_filePrtDepoWithd
 * @description file Prt Depo Withd 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_filePrtDepoWithd = async function () {
    const sbmOptions = {
        id: "tx_filePrtDepoWithd",
        method: "post",
        action: "/listInvstg/prtDepoList.do",
        ref: "dma_filePrtDepoWithdReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/listInvstg/lplAttach.do",
        ref: "dma_loadListReq",
        target: "dlt_attachList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function (action) {
    try { return await $c.data.downFile(action ?? "/listInvstg/lplAttach.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {String} prtDepoId prtDepoId
 * @param {*} prtDepoIdSeq prtDepoIdSeq
 * @param {*} fileSeq fileSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (prtDepoId, prtDepoIdSeq, fileSeq) {
    $c.util.getComponent('dma_FileDownReq').set('prtDepoId', prtDepoId);
    $c.util.getComponent('dma_FileDownReq').set('prtDepoIdSeq', prtDepoIdSeq);
    $c.util.getComponent('dma_FileDownReq').set('fileSeq', fileSeq);
    $c.util.getComponent('dma_FileDownReq').set('method', 'downloadPrtdepoFile');
    await scwin.tx_fn_FileDown('/listInvstg/lplAttach.do');
};

/**
 * @method
 * @name list
 * @description list 처리
 * @returns {void}
 * @hidden N
 */
scwin.list = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil52000/jldfil52000.xml');
};

/**
 * @method
 * @name filePrtDepoWithd
 * @description file Prt Depo Withd 처리
 * @param {*} type type
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.filePrtDepoWithd = async function (type) {
    if (type === "4") {
        let rse = await $c.win.confirm("재의무보유에 관한 첨부파일을 제출 하시겠습니까? ");
        if (rse) {
            scwin.form.action = '/listInvstg/prtDepoList.do';
            $c.util.getComponent('dma_FileDownReq').set('method', 'filePrtDepoWithd');
            { const __nr = await scwin.tx_filePrtDepoWithd(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil52000/jldfil52000.xml", { "method": 'filePrtDepoWithd' }); } };
        }
    } else {
        rse = await $c.win.confirm("재의무보유에 관한 첨부파일 수정 후 제출 하시겠습니까? ");
        if (rse) {
            scwin.form.action = '/listInvstg/prtDepoList.do';
            $c.util.getComponent('dma_FileDownReq').set('method', 'updateFilePrtDepoWithd');
            { const __nr = await scwin.tx_filePrtDepoWithd(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil52000/jldfil52000.xml", { "method": 'filePrtDepoWithd' }); } };
        }
    }
};
